#!/bin/bash
#
# Launcher for llama.cpp inference server.
#
#   1. Verify /var/lib/llama-cpp/models.ini exists (populated at service
#      startup as the dynamic user by llama-cpp-populate-models.py).
#   2. Start llama-server at reduced CPU priority so it does not starve the
#      desktop of resources.
#
set -euo pipefail

MODELS_INI="/var/lib/llama-cpp/models.ini"

# Ensure a preset exists before trying to start. models.ini is (re)generated by
# the service's ExecStartPre as the same dynamic user, so it is readable here.
if [[ ! -s "$MODELS_INI" ]]; then
    echo "llama-cpp-launcher: ${MODELS_INI} is missing or empty; refusing to start." >&2
    exit 1
fi

# Guard against an unset/empty LLAMA_CACHE (which would make mkdir try to
# create a directory named ""), then ensure the cache directory exists.
if [ -n "${LLAMA_CACHE:-}" ]; then
    mkdir -p "${LLAMA_CACHE}"
fi

# 2. Launch llama-server at lower CPU priority, like `nice -n 19`.
#    The priority is applied via the systemd unit's "Nice=" directive instead
#    of the "nice" binary here, because DynamicUser=yes drops CAP_SYS_NICE and
#    spawning "nice" would fail. The effect is identical to `nice -n 19`.
# Require the API key generated during first boot so clients must present it
# to use the server. The key is world-readable and the server only listens on
# loopback, so this is safe; skip the flag if the key was never generated so
# the service still starts in that case.
if [ -s /etc/llama-cpp/apikey ]; then
    echo "llama-cpp-launcher: requiring API key from /etc/llama-cpp/apikey"
    LLAMA_ARGS="${LLAMA_ARGS} --api-key-file /etc/llama-cpp/apikey"
fi

echo "llama-cpp-launcher: starting llama-server"
exec /usr/bin/llama-server \
    --models-preset "${LLAMA_PRESET:-$MODELS_INI}" \
    --host "${LLAMA_HOST:-127.0.0.1}" \
    --port "${LLAMA_PORT:-9931}" \
    ${LLAMA_ARGS}
